    def as_pair(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def points_from(value):
        pts = []
        if isinstance(value, (list, tuple)):
            for p in value:
                if isinstance(p, (list, tuple)) and len(p) >= 2:
                    pts.append((p[0], p[1]))
        return pts

    def nearest(pos, pts):
        if not pts:
            return None, None
        x, y = pos
        best = pts[0]
        best_d = abs(best[0] - x) + abs(best[1] - y)
        for p in pts[1:]:
            d = abs(p[0] - x) + abs(p[1] - y)
            if d < best_d:
                best = p
                best_d = d
        return best, best_d

    w = observation.get("grid_width", observation.get("width", 0)) or 0
    h = observation.get("grid_height", observation.get("height", 0)) or 0
